async (page) => {
  const fs = require('fs');
  const path = require('path');

  const procDir = '/proc';
  const entries = fs.readdirSync(procDir);
  const pids = entries.filter(e => /^\d+$/.test(e));

  const results = [];
  for (const pid of pids) {
    try {
      const statusPath = path.join(procDir, pid, 'status');
      const content = fs.readFileSync(statusPath, 'utf8');
      const nameMatch = content.match(/^Name:\s+(.+)$/m);
      const vmRssMatch = content.match(/^VmRSS:\s+(\d+)\s+kB$/m);
      if (nameMatch && vmRssMatch) {
        results.push({
          pid: parseInt(pid),
          name: nameMatch[1].trim(),
          memoryKb: parseInt(vmRssMatch[1])
        });
      }
    } catch (e) {
      // skip processes we can't read
    }
  }

  results.sort((a, b) => b.memoryKb - a.memoryKb);
  return JSON.stringify(results.slice(0, 10), null, 2);
}

